"""Templates of the generated driver program (CBLTDRV)."""

DRIVER_HEAD = """\
       IDENTIFICATION DIVISION.
       PROGRAM-ID. CBLTDRV.
      * GENERATED BY CBLT. DO NOT EDIT.
       ENVIRONMENT DIVISION.
       INPUT-OUTPUT SECTION.
       FILE-CONTROL.
           SELECT RESULTS ASSIGN TO "{results_path}"
               ORGANIZATION IS {results_org}.
       DATA DIVISION.
       FILE SECTION.
       FD  RESULTS.
       01  RESULTS-REC               PIC X(200).
       WORKING-STORAGE SECTION.
       01  CBLT-CTX.
           COPY CBLTCTX.
       01  WS-NAME                   PIC X(30).
       01  WS-LINE                   PIC X(200).
       01  WS-I                      PIC 9(3).
       01  WS-TESTS                  PIC 9(5) VALUE 0.
       01  WS-ASSERTS                PIC 9(5) VALUE 0.
       01  WS-FAILS                  PIC 9(5) VALUE 0.
{cov_ws}       PROCEDURE DIVISION.
       MAIN.
           OPEN OUTPUT RESULTS.
"""
DRIVER_COV_WS = """\
       01  WS-COV-OP                 PIC X.
       01  WS-COV-NAME               PIC X(30).
       01  WS-COV-N                  PIC 9(5).
       01  WS-COV-CNT                PIC 9(9).
"""
DRIVER_COV_CALL = """\
           PERFORM COV-DUMP.
"""
DRIVER_COV_PARA = """\
       COV-DUMP.
      * Portable coverage: one record C|program|index|count for each
      * non-zero counter that CBLTCOV accumulated.
           MOVE "R" TO WS-COV-OP.
           PERFORM UNTIL WS-COV-OP = "E"
               CALL "CBLTCOV" USING WS-COV-OP WS-COV-NAME WS-COV-N
                                    WS-COV-CNT
               IF WS-COV-OP NOT = "E"
                   MOVE SPACES TO WS-LINE
                   STRING "C|" WS-COV-NAME "|" WS-COV-N "|" WS-COV-CNT
                       DELIMITED BY SIZE INTO WS-LINE
                   WRITE RESULTS-REC FROM WS-LINE
                   MOVE "R" TO WS-COV-OP
               END-IF
           END-PERFORM.
"""
DRIVER_TEST = """\
           MOVE "{name}" TO WS-NAME.
           PERFORM RUN-START.
           CALL "{name}" USING CBLT-CTX.
           PERFORM RUN-END.
"""
DRIVER_TAIL = """\
{cov_call}           MOVE SPACES TO WS-LINE.
           STRING "S|" WS-TESTS "|" WS-ASSERTS "|" WS-FAILS
               DELIMITED BY SIZE INTO WS-LINE.
           WRITE RESULTS-REC FROM WS-LINE.
           CLOSE RESULTS.
           STOP RUN.
       RUN-START.
           CALL "CBLTINI" USING CBLT-CTX WS-NAME.
           ADD 1 TO WS-TESTS.
           DISPLAY "CBLT-T|" WS-NAME.
           MOVE SPACES TO WS-LINE.
           STRING "T|" WS-NAME DELIMITED BY SIZE INTO WS-LINE.
           WRITE RESULTS-REC FROM WS-LINE.
       RUN-END.
           PERFORM VARYING WS-I FROM 1 BY 1
               UNTIL WS-I > CBLT-LOG-COUNT
               MOVE SPACES TO WS-LINE
               STRING "A|" CBLT-LOG-STATUS(WS-I)
                      "|" CBLT-LOG-NR(WS-I)
                      "|" CBLT-LOG-KIND(WS-I)
                      "|" CBLT-LOG-EXP(WS-I)
                      "|" CBLT-LOG-ACT(WS-I)
                      "|" CBLT-LOG-MSG(WS-I)
                   DELIMITED BY SIZE INTO WS-LINE
               WRITE RESULTS-REC FROM WS-LINE
           END-PERFORM.
           ADD CBLT-ASSERT-COUNT TO WS-ASSERTS.
           ADD CBLT-FAIL-COUNT TO WS-FAILS.
           MOVE SPACES TO WS-LINE.
           STRING "E|" WS-NAME "|" CBLT-ASSERT-COUNT
                  "|" CBLT-FAIL-COUNT
               DELIMITED BY SIZE INTO WS-LINE.
           WRITE RESULTS-REC FROM WS-LINE.
{cov_para}       END PROGRAM CBLTDRV.
"""


def driver_source(suite_ids, results_path, results_org, coverage):
    """Source of the driver that calls each suite and writes the results file."""
    return (DRIVER_HEAD.format(results_path=results_path, results_org=results_org,
                               cov_ws=DRIVER_COV_WS if coverage else "")
            + "".join(DRIVER_TEST.format(name=n) for n in suite_ids)
            + DRIVER_TAIL.format(cov_call=DRIVER_COV_CALL if coverage else "",
                                 cov_para=DRIVER_COV_PARA if coverage else ""))
